//! Channel constants. Prod builds with `--no-default-features` (Ctrl+Alt+U); Dev uses the
//! default `dev` feature (Ctrl+Alt+D). Both run side by side. Never hardcode these elsewhere.
//! `DISPLAY_NAME` and `VERSION` are generated by build.rs because the exe resources need them.
include!(concat!(env!("OUT_DIR"), "/channel.rs"));

pub const IS_DEV: bool = cfg!(feature = "dev");
pub const CHANNEL: &str = if IS_DEV { "dev" } else { "prod" };
/// Logs and Prod settings live here; never inside Velopack's install root (`LEGACY_FOLDER`).
pub const SHARED_DATA_FOLDER: &str = "UniversalSpellCheck.Data";
pub const DATA_FOLDER: &str = if IS_DEV {
    "UniversalSpellCheck.Dev"
} else {
    SHARED_DATA_FOLDER
};
pub const LEGACY_FOLDER: &str = "UniversalSpellCheck";
pub const MUTEX: &str = if IS_DEV {
    "UniversalSpellCheck.Dev"
} else {
    "UniversalSpellCheck"
};
pub const HOTKEY_VK: u32 = if IS_DEV { 0x44 } else { 0x55 };
pub const EVIDENCE_MUTEX: &str = "Local\\UniversalSpellCheck.DeveloperEvidence";
pub const MIGRATION_MUTEX: &str = "UniversalSpellCheck.DataMigration.v1";
/// Ctrl+Alt+F24: SendInput can press it but no physical keyboard has it, so bench runs never
/// collide with a product channel or another app.
pub const BENCH_VK: u32 = 0x87;
pub const BENCH_TITLE: &str = "UniversalSpellCheck.Bench.Rust";

pub fn hotkey_title() -> String {
    format!("{MUTEX}.HotkeyWindow")
}
pub fn update_message() -> String {
    format!("{MUTEX}.UpdateRequested")
}
